"use client";
import type { ReactNode } from "react";
import "./hud-frame.css";

/** A targeting frame for any content: corner brackets, scan line, and readouts. */
export function HudFrame({
  children,
  label = "Target",
  status = "Live",
  code = "SIG-01",
  className = "",
}: {
  children?: ReactNode;
  label?: string;
  status?: string;
  code?: string;
  className?: string;
}) {
  return (
    <div className={`forme-hud ${className}`}>
      <span className="forme-hud-corner" data-corner="tl" aria-hidden="true" />
      <span className="forme-hud-corner" data-corner="tr" aria-hidden="true" />
      <span className="forme-hud-corner" data-corner="bl" aria-hidden="true" />
      <span className="forme-hud-corner" data-corner="br" aria-hidden="true" />
      <span className="forme-hud-scan" aria-hidden="true" />
      <div className="forme-hud-bar">
        <span>{label}</span>
        <span className="forme-hud-status">
          <i aria-hidden="true" />
          {status}
        </span>
      </div>
      <div className="forme-hud-body">{children}</div>
      <div className="forme-hud-bar" aria-hidden="true">
        <span>{code}</span>
        <span className="forme-hud-ticks" />
      </div>
    </div>
  );
}

.forme-hud {
  --forme-hud-accent: #4df3ff;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 240px;
  padding: 18px 20px;
  border: 1px solid #ffffff12;
  border-radius: 14px;
  background: radial-gradient(120% 90% at 50% 0%, #4df3ff0d, transparent 60%), #08090c;
  color: #e6f6fa;
  overflow: hidden;
  isolation: isolate;
}
.forme-hud-corner {
  position: absolute;
  width: 14px;
  height: 14px;
  border: 0 solid var(--forme-hud-accent);
  opacity: 0.9;
  animation: forme-hud-lock 0.7s cubic-bezier(0.2, 0.9, 0.2, 1) both;
}
.forme-hud-corner[data-corner="tl"] { top: 8px; left: 8px; border-width: 1.5px 0 0 1.5px; border-top-left-radius: 4px; --forme-hud-from: -10px, -10px; }
.forme-hud-corner[data-corner="tr"] { top: 8px; right: 8px; border-width: 1.5px 1.5px 0 0; border-top-right-radius: 4px; --forme-hud-from: 10px, -10px; }
.forme-hud-corner[data-corner="bl"] { bottom: 8px; left: 8px; border-width: 0 0 1.5px 1.5px; border-bottom-left-radius: 4px; --forme-hud-from: -10px, 10px; }
.forme-hud-corner[data-corner="br"] { bottom: 8px; right: 8px; border-width: 0 1.5px 1.5px 0; border-bottom-right-radius: 4px; --forme-hud-from: 10px, 10px; }
.forme-hud-scan {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 40%;
  z-index: -1;
  background: linear-gradient(transparent, #4df3ff0a 85%, #4df3ff2e 100%);
  animation: forme-hud-scan 3.2s linear infinite;
}
.forme-hud-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 0 6px;
  font-size: 12px;
  line-height: 1;
  color: #8fb3bd;
}
.forme-hud-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--forme-hud-accent);
}
.forme-hud-status i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 10px currentColor;
  animation: forme-hud-blink 1.4s steps(1) infinite;
}
.forme-hud-ticks {
  flex: 1;
  max-width: 120px;
  height: 6px;
  background: repeating-linear-gradient(90deg, #7fb4c2 0 1px, transparent 1px 6px);
  opacity: 0.6;
}
.forme-hud-body {
  flex: 1;
  display: grid;
  place-items: center;
}
@keyframes forme-hud-lock {
  from { transform: translate(var(--forme-hud-from)); opacity: 0; }
}
@keyframes forme-hud-scan {
  from { transform: translateY(-100%); }
  to { transform: translateY(250%); }
}
@keyframes forme-hud-blink {
  50% { opacity: 0.2; }
}
@media (prefers-reduced-motion: reduce) {
  .forme-hud-corner,
  .forme-hud-scan,
  .forme-hud-status i {
    animation: none;
  }
  .forme-hud-scan {
    display: none;
  }
}
